insert into matcha_articles (url, lang, prefecture_code, title, body, images, published_at, place, text_attribution, text_attribution_url)
values
(E'https://matcha-jp.com/tw/26796', E'zh-Hant', 17, E'金澤必訪米其林餐廳推薦：壽司、和牛與懷石料理', E'探索金澤五間頂級米其林餐廳，從星級懷石料理，到金澤站附近的奢華壽司與和牛饗宴，一次網羅。\n\n金澤是一座以優雅工藝與文化聞名的城市，將料理傳統與現代創新巧妙融合，並充分運用來自日本海的豐饒海產資源。\n\n從米其林星級懷石料理到當代風格海鮮酒吧，以下五間餐廳展現了這座城市頂尖的旬味職人技藝與不斷進化的美食風貌。\n\n立喰い鮨 優勝將金澤原本偏向正式的壽司文化重新詮釋，打造北陸地區首間正宗立食壽司店。', E'["https://resources.matcha-jp.com/resize/720x2000/2026/03/13-260986.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/13-260987.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/13-260988.webp","https://resources.matcha-jp.com/resize/720x2000/2026/03/23-261455.webp"]'::jsonb, E'2026-06-08'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/22468', E'zh-Hant', 17, E'金澤必吃美食10選！午餐、晚餐、下午茶就吃這些餐廳！', E'金澤是一座以四季美景和豐富文化而自豪的城市,這裡有許多值得品嚐的當地美食。從用金箔點綴的甜點,到美味的螃蟹料理,再到使用地瓜製作的特色菜餚,應有盡有。讓我們一起來看看在金澤不可錯過的10種名產料理和飲品\n\n金澤是以日本精緻文化而聞名的城市。身為石川縣最大的城市，它以生產金箔、江戶時代的武士階級和高水準的藝術文化而著稱。\n\n現代金澤是一座傳統文化與現代文化完美融合的城市，被譽為活力四射的藝術場景和日本隱藏美食的寶地。金澤位於石川縣狹長地形的中央，四周被山和海環繞，擁有獨特的氣候與深厚的歷史。尤其在冬季，沉重的濕雪為這裡增添了多樣的冬季美食特色。\n\n喜歡安靜享用甜點的人可以到傳統的東茶屋街上的「烏雞庵」，這裡提供搭配金箔的美麗蛋糕和茶，也可以作為手信帶回家。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/01-207211.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/01-207212.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/01-207218.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/01-207220.webp"]'::jsonb, E'2024-11-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/4227', E'zh-Hant', 18, E'【福井】米其林綠色指南景點「永平寺」完全導覽：道元禪師開山、七堂伽藍與坐禪體驗', E'永平寺是福井著名的曹洞宗總院，由道元禪師於1244年創建，是日本重要的禪修道場。寺內以七堂伽藍與迂迴廊道群組成，僧侶（雲水）嚴格修行，遊客可參加坐禪體驗或品嘗精進料理。四季變化帶來不同景致：春青苔、夏綠蔭、秋楓紅、冬雪景。此外，山門、傘松閣等處被視為能量加持點，傳說撫摸大庫院擂粉木或品嚐芝麻豆腐能帶來好運。\n\n永平寺是福井縣北部一座歷史悠久靜謐古雅的禪寺。是日本禪宗支派曹洞宗的總院，作為禪宗信仰的中心聞名於世，是喜愛禪學，渴望尋找自我的人士一生必來朝聖的聖地。\n\n永平寺坐落在三方群山環繞之地，南側有溪水潺潺流經，境內古木參天，鬱鬱蔥蔥。寺院建築和周遭自然融合一體，景觀引人入勝，在米其林綠色指南獲得二星評價。同時，永平寺也是一個著名的能量景點。風水師分析這裡是四神相應地形，非常吉祥。不知是風水磁場使然，還是山林釋放芬多精所致，永平寺總是洋溢著寧靜安祥的氛圍。\n\n永平寺是距今約770前的寬元二年（1244年）由道元禪師創辦的坐禪修行道場。道元禪師於宋朝時越洋遠赴中國，在天童寺如淨禪師的門下學佛修行，返日後著作『普勸坐禪儀』將曹洞宗禪學傳入日本，提倡「只管打坐」禪法。因為越前國（福井的古名）的領主波多野義重公的邀請，才把自己的修禪道場移到越前國這個地點的。在日本南北朝時代，受天皇冊封為「曹洞宗第一道場」。從道元祖師開山至今，雖然永平寺曾經幾次因為戰亂勢力變小，也幾次遭受祝融之災。不過，永平寺歷代傳承，共傳了七十九代，現任住職是玄德禪師。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/03/29-22692.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/29-22694.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/29-22696.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/29-22698.webp"]'::jsonb, E'2017-08-08'::timestamptz, E'永平寺', null, null),
(E'https://matcha-jp.com/tw/4559', E'zh-Hant', 18, E'福井車站必買：HAPPRING 一次收集9大在地伴手禮推薦', E'R福井車站西口的綜合商場「ハピリンHAPPRING」聚集福井代表性伴手禮與工藝品，從入口即化的羽二重餅、獲獎的五月ヶ瀬煎餅、清爽的越前蕎麥麵，到獨特的へしこ鯖與名酒「梵」，以及越前和紙、越前漆器、越前燒與鯖江製眼鏡。文章整理每項特色與購買建議，讓初訪福井的旅客能輕鬆一次買齊名物。\n\n選購伴手禮是旅遊中的樂趣之一，來福井縣旅遊當然也會想帶這裡的特色伴手禮回家。今天MATCHA小編要介紹在JR福井車站西口的綜合設施「ハピリンHAPPRING」，在這裡就能買到的福井人最愛福井縣好物九選。讓你初訪福井縣也能輕輕鬆鬆一次購齊特色伴手禮。\n\n為了準備北陸新幹線延伸至福井縣，三年前JR福井車站以「恐龍王國」為設計主題重新改頭換面。車站西口福井新地標－綜合設施「ハピリンHAPPRING」落成開幕後，福井車站前重新散發時尚的新樣貌。而「ハピリンHAPPRING」的一、二樓商場更為了迎接觀光客的到來，特別將福井縣具代表性的各式伴手禮、工藝品及「MADE IN FUKUI」的優質商品都集在這裡展售。一次通通買齊，非常好逛。\n\n福井縣最具代表性的和菓子。羽二重餅是傳統的日式麻糬，口感綿密，入口即化，香甜美味。它的名字來自明治時代福井盛產的高級紡織品「羽二重織」。據說羽二重織非常昂貴，一般都外銷，反而當地人見都沒見過。當年和菓子師傅就是為了讓當地人一睹羽二重織像珍珠般的光澤跟優雅，而創作出羽二重餅。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/06/12-28649.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/12-28650.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/12-28651.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/12-28652.webp"]'::jsonb, E'2017-06-16'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/4046', E'zh-Hant', 18, E'【福井】越前大野雛祭完全指南：二千個雛人形與傳統工藝展覽', E'雛祭（女兒節）為日本三月三日的傳統節慶，家家為女兒擺設雛人形祈求健康成長。越前大野舉辦的「粉彩春天 越前大野的雛祭」以二十層高臺展示超過兩千尊雛人形，從江戶古董到現代趣味款一應俱全，並展出越前和紙、竹人形與陶雛等在地工藝。展品多由市民捐贈，兼具文化傳承與觀光魅力；2021年因疫情停辦，未來展期請以主辦單位公告為準。\n\n隨著春天的脚步漸近，一年一度的「雛祭」（ひなまつり）女兒節又將來到。三月三日的女兒節，也稱爲「桃花節」（もものせっく）。按照日本的傳統習俗，當家中女嬰第一次迎接女兒節時，母親娘家就會為孩子準備一組「雛人形」（ひなにんぎょう）女兒節娃娃贈送給女孩，祝福孩子健康平安成長。\n\n正式的雛人形組合是依照平安時期宮廷貴族的裝扮來製作。特別尊容華貴的主要人形代表著天皇和皇后，衣飾華麗講究，天皇會戴著烏帽子（えぼうし），皇后人形身上穿的則是有名的十二單（じゅうにひとえ）。\n\n昂貴的豪華版雛人形有七層之多，最上層的天皇和皇后外，還會有女官、侍從、大臣和護衛等等。佈景裝飾也有規矩。臺階式的裝飾台上會鋪著紅色的地毯，天皇和皇后的後面會放金屏風，兩旁則擺放燈飾和桃花，最下排還會放有馬車轎子，第六排則是鏡臺、衣箱、火爐等生活道具，象徵著女孩豐厚的嫁妝。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/02/21-19198.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/21-19197.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/21-19196.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/21-19207.webp"]'::jsonb, E'2017-02-24'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/23661', E'zh-Hant', 19, E'新倉山淺間公園', E'新倉山淺間公園（日語：新倉山浅間公園、あらくらやませんげんこうえん）是位於日本山梨縣富士吉田市新倉的一座公園，設立於1959年10月。\n\n這座公園因其可一覽富士山及櫻花的景觀而具有頗高人氣。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/21-220245.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/21-220246.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/21-220247.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/21-220239.webp"]'::jsonb, E'2025-01-30'::timestamptz, E'新倉山淺間公園', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E6%96%B0%E5%80%89%E5%B1%B1%E6%B7%BA%E9%96%93%E5%85%AC%E5%9C%92'),
(E'https://matcha-jp.com/tw/21838', E'zh-Hant', 19, E'山中湖', E'山中湖是富士山在山梨縣一側的淡水湖，並坐落在山中湖村內。該湖為富士五湖之一，也是其中面積最大且湖面標高最高的湖泊，在全日本則位居第3。\n\n山中湖也是富士五湖中水深最淺的湖泊，全域則位於富士箱根伊豆國立公園的範圍內。二月山中湖的大事紀包括以「鑽石富士山」出現時間，從「山中簗尻」到「筑波大學寮前浜」一帶，舉行「鑽石富士山與冰蠟燭」祭典。\n\n為期近一個月的「冰蠟燭祭典」，晚上5點30分開始點燈及施放煙火。燃放煙火的場地分別在長池浜、平野ちびっこ廣場、山中湖交流廣場「きらら」。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/04-200566.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/04-200574.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/04-200567.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/04-200568.webp"]'::jsonb, E'2024-10-08'::timestamptz, E'山中湖', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%B1%B1%E4%B8%AD%E6%B9%96'),
(E'https://matcha-jp.com/tw/7470', E'zh-Hant', 19, E'河口湖', E'河口湖（日語：河口湖／かわぐちこ，羅馬化：Kawaguchi-ko）是位於山梨縣富士河口湖町的湖泊。為富士五湖之一。富士箱根伊豆國立公園的一部分。\n\n是富士五湖中湖岸線最長、標高最低的一湖。面積在富士五湖中位於第二。最大水深與精進湖並列第三。湖中央有一名為鵜之島（鸕鷀島）的小島。\n\n也是富士五湖中最北的一湖。湖畔旅館環繞，天氣晴朗時湖中富士山倒影相映為一絕景，為富士山附近知名景點。湖畔的產屋崎（日語：産屋ヶ崎）是眺望富士山的景點。\n\n另外，乳崎、小曲岬（子轉崎）、長崎（胞崎）等也是知名景點。2013年6月22日，河口湖以「富士山-信仰的對象和藝術的源泉」的構成資產之一，登錄為世界文化遺產。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/31-78347.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/31-78332.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/31-78333.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/31-78344.webp"]'::jsonb, E'2019-05-24'::timestamptz, E'河口湖', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E6%B2%B3%E5%8F%A3%E6%B9%96'),
(E'https://matcha-jp.com/tw/9426', E'zh-Hant', 20, E'【2026】長野賞櫻攻略：上田城、松本城到中綱湖的8大櫻花景點與最佳賞期', E'長野縣擁有豐富且古老的櫻花資源，南北縱深的地形使得各地花期錯落延長，從早開的高遠城址到高地的中綱湖，賞櫻時間可跨越數週。本篇介紹八處代表性景點（高遠城址公園、上田城、光前寺、小諸懷古園、中綱湖、上川河川敷、松本城、馬見塚公園），並提供推估最佳觀賞期與交通資訊，方便旅人規劃自駕或搭乘大眾運輸的賞櫻行程。\n\n得天獨厚的長野擁有許多鬼斧神工的自然秘境，或許很多人還不知道長野也是日本種植最多古老櫻花之地。而南北縱貫的狹長地形，開花時期各地皆有不同，也促使賞花時期拉長，想要看滿開的、還是櫻吹雪的，若是密切注意長野的開花狀況，說不定都可以在長野尋覓到一處心目中最完美的櫻之絕景。\n\n推估最佳觀賞期：2026/4/6 – 4/12，請參考官方網站。 地址：長野県伊那市高遠町東高遠 交通方式：【電車】JR飯田線伊那市站轉搭高遠線巴士約25分 下車後徒歩約15分\n\n推估最佳觀賞期：2026/4/8 – 4/14 千本櫻活動日期：2026年尚未確定，詳情請洽官方網站。 地址：長野県上田市二の丸 交通方式：JR北陸新幹線到上田站下車，徒歩12分 上田城跡公園', E'["https://resources.matcha-jp.com/resize/720x2000/2020/02/14-97070.webp","https://resources.matcha-jp.com/resize/720x2000/2020/02/14-97081.webp","https://resources.matcha-jp.com/resize/720x2000/2017/03/04-20487.webp","https://resources.matcha-jp.com/resize/720x2000/2020/02/14-97071.webp"]'::jsonb, E'2020-02-14'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/22174', E'zh-Hant', 20, E'【長野】上高地的楓葉最佳觀賞時期是什麼時候？賞楓人潮資訊和推薦景點介紹！', E'長野縣的上高地紅葉時期從9月下旬開始，最佳觀賞期為10月中旬至11月上旬，河童橋和大正池是非常受歡迎的景點，還可以欣賞到雪覆蓋的穗高連峰！我們還會介紹紅葉季節的賞楓人潮資訊和交通方式（接駁巴士、停車場）等內容。\n\n上高地的紅葉開始得早，從9月下旬開始，山上的涸澤（からさわ）已進入最佳觀賞期，隨後顏色逐漸轉移到山腳下。\n\n到了10月中旬，楓樹、七竅紅、落葉松等開始美麗地變色，穗高連峰和梓川的景觀更加突出。\n\n在10月下旬，山頂開始積雪，如果運氣好的話，您可以享受到紅葉與雪的對比這一珍貴的體驗，這也是上高地秋季的一大魅力。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/21-204098.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/21-204099.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/21-204100.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/21-204101.webp"]'::jsonb, E'2024-10-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/3093', E'zh-Hant', 20, E'【2026】長野縣完全旅遊指南：野澤溫泉、白馬滑雪場、地獄谷猴子、松本城、輕井澤必訪景點一次看', E'長野縣以豐富自然、溫泉與滑雪場聞名，人氣景點包括冬季在溫泉中泡湯的地獄谷野猿公苑、被稱為「烏鴉城」的國寶松本城，以及充滿洋溢文化氣息的輕井澤度假區。本文整理從東京出發的交通方式（北陸新幹線、夜行巴士與自駕）、縣內交通、推薦周遊券與各區域亮點，並介紹必訪溫泉、神社寺廟與美食，適合計畫長野深度旅遊的旅客參考。\n\n在眾多景點中，特別以地獄谷野猿公苑最為具有人氣，在這裡還能看到在溫泉裡享受的猴子們。此外，像是因牆的顏色和與全黑的烏鴉相同, 因而有「烏鴉城」名稱的松本城等地都是十分有名的觀光地。\n\n2016年，伴隨著NHK大河劇《真田丸》的播出，作為故事舞臺的上田城也再度引起了人們的注目。\n\n除此之外，作為日本別墅地而享有很高盛名的輕井澤也是十分值得一去的觀光地。在輕井澤有許多度假飯店、茶沙龍和博物館，是個十分具有文化氣息的地方。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/02/14-122635.webp","https://resources.matcha-jp.com/archive_files/jp/2016/06/DSC01521-1024x683.webp","https://resources.matcha-jp.com/archive_files/jp/2016/05/tokyo_to_nagoya_20160125e2.webp","https://resources.matcha-jp.com/resize/720x2000/2016/10/25-6582.webp"]'::jsonb, E'2017-04-13'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24230', E'zh-Hant', 21, E'岐阜縣警察', E'岐阜縣警察（日語：岐阜県警察／ぎふけんけいさつ，羅馬化：Gifu ken keisatsu）是日本岐阜縣的警察機關，由岐阜縣政府下設的岐阜縣公安委員會管轄。\n\n至2025年，岐阜縣警察設有22個警察署，警官總數3,536人。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/21-225471.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/21-225472.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/21-225473.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/21-225474.webp"]'::jsonb, E'2025-03-06'::timestamptz, E'岐阜縣警察', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%B2%90%E9%98%9C%E7%B8%A3%E8%AD%A6%E5%AF%9F'),
(E'https://matcha-jp.com/tw/22204', E'zh-Hant', 21, E'岐阜縣警察', E'岐阜縣警察（日語：岐阜県警察／ぎふけんけいさつ，羅馬化：Gifu ken keisatsu）是日本岐阜縣的警察機關，由岐阜縣政府下設的岐阜縣公安委員會管轄。\n\n至2025年，岐阜縣警察設有22個警察署，警官總數3,536人。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/10/22-204287.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/22-204289.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/22-204292.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/22-204294.webp"]'::jsonb, E'2024-10-23'::timestamptz, E'岐阜縣警察', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%B2%90%E9%98%9C%E7%B8%A3%E8%AD%A6%E5%AF%9F'),
(E'https://matcha-jp.com/tw/9679', E'zh-Hant', 21, E'【2026】岐阜縣必去精選景點14選！白川鄉、飛驒高山、莫內之池、馬籠宿都在這！', E'岐阜縣擁有世界遺產的白川鄉合掌村與飛驒高山等著名景點，更有不少優美景致和獨特文化的觀光景點！除此之外本文也將介紹岐阜縣精選景點外，還跟您介紹當地祭典、當地美食資訊， 介紹您岐阜縣的魅力。\n\n岐阜縣近乎位於日本列島的正中央，就在名古屋的北方。這群山圍繞之下的富饒自然景觀耐人尋味，並保留著眾多歷史悠久的街道和村莊，是一處魅力無限的地區。\n\n岐阜縣南北氣候和風俗各有不同，北部被稱為「 飛驒地區」、南部被稱為「美濃地區」，這些地方均有著名的觀光景點。\n\n岐阜縣的南北氣候不太相同，但都是被群山圍繞的城市，所以基本上比較涼爽，冬天也較嚴寒。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/06/01-138849.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/13-101306.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/13-101307.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/13-101308.webp"]'::jsonb, E'2020-05-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/6031', E'zh-Hant', 22, E'富士山', E'63公尺，是日本國內的最高峰。富士山頂冬季積雪，直至次年6、7月才會融化，在管理上屬於本州地區的富士箱根伊豆國立公園範圍內。\n\n在富士山山麓周圍，分布着5個淡水湖，統稱富士五湖，是日本著名的觀光度假名勝地。富士山有4個主要的登山口，分別為富士宮口、須走口、御殿場口、富士吉田（河口湖）口等，其中前三個登山入口都在靜岡縣內。\n\n富士山被日本人視為聖山，不但名列日本百名山，同時也是日本三名山之一，在古代文獻中亦被稱為不二、不盡或是富慈，也經常被稱作芙蓉峰、富嶽或富岳。\n\n自古以來，這座山的名字就經常在日本的傳統詩歌和歌中出現。富士山與櫻花、新幹線並列為日本的國家象徵。富士山與淺間神社等範圍以富士山於2013年6月22日以精神信仰與藝術層面正式獲選列入世界文化遺產，是日本的第17個世界遺產（第13個世界文化遺產）。富士山除了特指此座山脈，還有一系列「鄉土富士」，即遍布日本全國各地帶有「富士」名稱的山，比如羊蹄山等外型相似的山脈。', E'["https://resources.matcha-jp.com/resize/720x2000/2026/02/16-258758.webp","https://resources.matcha-jp.com/resize/720x2000/2018/04/24-52908.webp","https://resources.matcha-jp.com/resize/720x2000/2018/05/22-54539.webp","https://resources.matcha-jp.com/resize/720x2000/2018/04/24-52909.webp"]'::jsonb, E'2019-04-10'::timestamptz, E'富士山', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%AF%8C%E5%A3%AB%E5%B1%B1'),
(E'https://matcha-jp.com/tw/25447', E'zh-Hant', 22, E'從東京出發僅需兩小時，探索伊豆修善寺全新魅力之旅 —— 地藏雕刻與山葵特別體驗', E'自古以來便以溫泉勝地聞名的伊豆修善寺地區，被譽為「小京都」的這座小鎮，是一處能夠享受只有在此地才能體驗的獨特旅遊樂趣的觀光勝地。 本篇文章將為您介紹在修善寺地區可以親身體驗的美食、文化與傳統等特別體驗。\n\n自古以來就以溫泉鄉聞名的修善寺，實際上也是被認定為「世界農業遺產」的山葵栽培聖地。在這裡，您可以品嚐到運用清澈水源孕育出的山葵，以及當地的精釀啤酒、日本清酒與葡萄酒等，充分展現大自然恩賜的在地美味。\n\n在那樣的城鎮中心，有一座被傳說由約1200年前對日本佛教影響深遠的高僧——弘法大師空海所開創的「修禪寺」。這個地方擁有將軍源賴家被幽禁的歷史背景，至今仍能感受到某種莊嚴的氣氛。\n\n這次將為您介紹幾個能深入體驗修善寺文化、美食與歷史的景點。邀您展開一場五感皆能感受的全新修善寺之旅。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/23-239318.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/23-239451.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/23-239319.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/23-239494.webp"]'::jsonb, E'2025-09-26'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/25794', E'zh-Hant', 22, E'伊豆高級旅館「三養莊」體驗四季之美與文化魅力', E'入住位於伊豆溫泉鄉的高級旅館「三養莊」，親身感受日本四季的美麗風情，並透過賞楓、賞櫻、藝伎款待等文化體驗，享受充滿雅趣的時光。\n\n位於伊豆半島的「三養莊」，是一家擁有廣闊日式庭園、引入京都庭園美學的高級旅館。這裡是想要欣賞四季自然變化、同時享受溫泉的最佳住宿選擇。\n\n在三養莊，旅客可透過隨季節變化推出的住宿方案及館內舉辦的文化體驗活動，更深入感受日本文化的魅力。本文將為您介紹依自然與四季更迭而設計的特別住宿方案。\n\n三養莊最迷人的魅力之一，莫過於那座美麗的日式庭園。這座借景式庭園由京都知名庭師小川治兵衛於1920年代後期打造，巧妙地將廣闊的景觀濃縮於其中，呈現出層次豐富的景致。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/09/10-244002.webp","https://resources.matcha-jp.com/resize/720x2000/2025/10/27-248197.webp","https://resources.matcha-jp.com/resize/720x2000/2025/09/10-244004.webp","https://resources.matcha-jp.com/resize/720x2000/2025/10/27-248198.webp"]'::jsonb, E'2025-10-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7258', E'zh-Hant', 23, E'【名古屋】 市場、市集、商店街！走進在地人的日常購物享食景點4選', E'名古屋市區其實有很多能夠感受在地風情的市集,商店街與市場以及歷史建築地區，這次我們將介紹在地人也常去的採買購物，品嚐美食的景點店家給想體會名古屋人情味的大家！\n\n對於生活在當地的人來說，市場，市集與商店街是習以為常的採購場所，這篇將帶大家走一趟不一樣的名古屋，到市場品嚐海鮮，在市集挖寶手作小物，在熱鬧的商店街吃遍小吃，體驗不一樣卻最真實的名古屋之旅。\n\n除了提供給專業料理人最新鮮的食材之外，也歡迎一般顧客光顧，且能以實惠的價格購買到當日捕獲的海鮮，部分店家也有販售可以現吃也可作為關東煮或鍋物食材的魚加工品（圖為洋蔥魚加工品49日圓含稅）。不只如此，午餐與晚間部分店家會以居酒屋與餐廳形式開店，因此不時可以看到上班族們排隊等著吃上一頓美食的盛況呢。\n\n天ぷらとワイン小島的店主因愛吃天婦羅，加上曾在義大利料理店進修，因此決心推出適合配酒吃的天婦羅，將日本料理新添創意與可能性。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/04/05-74421.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/05-74422.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/05-74400.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/05-74406.webp"]'::jsonb, E'2019-04-03'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24141', E'zh-Hant', 23, E'名古屋城', E'名古屋城是位於日本愛知縣名古屋市的城堡。江戶時代是尾張藩藩主居城，別稱「金城」、「金虎鯨城」（日文漢字：金鯱城）。日本100名城之一。\n\n前身為織田氏居城那古野城。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/18-224864.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/18-224842.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/18-224857.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/18-224861.webp"]'::jsonb, E'2025-02-17'::timestamptz, E'名古屋城', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%90%8D%E5%8F%A4%E5%B1%8B%E5%9F%8E'),
(E'https://matcha-jp.com/tw/23571', E'zh-Hant', 23, E'【名古屋】走訪喫茶店王國！體驗道地喫茶文化老舖4選', E'被譽為「喫茶王國」之一的愛知縣名古屋，根據2021年的調查約有 6,171間，僅次於第一名的大阪府。在競爭激烈喫茶店市場中，有哪些喫茶店是絕對必訪的呢？跟著小編來探索昭和風復古喫茶之旅吧！\n\n1960～80年代是喫茶店最興盛時期，由於名古屋當時地價便宜，因此吸引大量人潮開創喫茶店。名古屋的喫茶店與日本其他地區的喫茶店有著不同的獨特文化，那就是「買咖啡送早餐」。喫茶店早餐文化源自於愛知縣一宮市，這座城市曾經以紡織業而繁盛。由於市街中紡織工廠林立，吵雜的機械聲使得員工們無法與客戶商談，而轉到鄰近的喫茶店，一邊喝咖啡談正事。\n\n因此喫茶店老闆為了回饋他們，提供了水煮蛋和一些花生的服務。就這樣點一杯飲料的就會附贈一些食物的服務逐漸廣為人知，發展成現今名古屋喫茶早餐，買咖啡送吐司、水煮蛋或是味噌湯等，特殊飲食文化。\n\n創業於1949年的洋菓子喫茶「BON BON」，代代傳承了二戰期間與德國人學習製作西點蛋糕的技術，超過30種以上的甜點，每樣甜點簡單樸實，保留著小時候曾經吃過的味道，且價格親民到每一個都想點來品嚐。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/01/10-218516.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/10-218526.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/10-218525.webp","https://resources.matcha-jp.com/resize/720x2000/2025/01/10-218528.webp"]'::jsonb, E'2025-01-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/9742', E'zh-Hant', 24, E'【三重】放緩腳步漫遊松阪景點！遊城跡、品嚐超值懷石料理', E'到松阪市來趟一天小旅行，除了能品嚐和牛與懷石料理之外，在松阪市內也有不少歷史、文化相關景點，例如武家屋敷、遊覽松阪城跡和體驗松阪傳統工藝等等，大部份皆為可從車站步行抵達的範圍，相當方便。來松阪市玩一天之後，不只能得到味蕾的滿足，也可以令心靈更加充實。\n\n到松阪市來趟一天小旅行，除了能品嚐和牛之外，在松阪市內也有不少值得探訪的景點，例如武家屋敷、遊覽松阪城跡和體驗松阪傳統工藝等等，大部份皆為可從車站步行抵達的範圍，相當方便。\n\n繼松寺山號原為「岡寺山」，相傳繼松寺是聖武天皇時興建的，當時是天皇為了行基菩薩而建造。那時奈良正在興建東大寺，繼松寺是為了用來祈求東大寺的興建順利。\n\n這裡供奉厄除觀音，剛好當時又適逢聖武天皇42歲厄年之際（類似犯太歲），他就供奉這位觀音來褓祐自己。以後許多松阪人都會在自己厄年的年份和3月的初午大祭（3月8日－9日）特地前來參拜，以祈求自己該年事事順利。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/04/29-102314.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/29-102315.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/29-102309.webp","https://resources.matcha-jp.com/resize/720x2000/2020/04/29-102307.webp"]'::jsonb, E'2020-04-29'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/23977', E'zh-Hant', 24, E'【三重】松阪市美食完整指南！從松阪牛到在地人激讚的雞肉燒肉、甜點與觀光資訊全攻略', E'位於三重縣中部的松阪市是座美食寶庫。從著名的松阪牛肉，到當地人喜愛的雞肉燒肉和甜點，可在此享受各式各樣美味料理。本文將精選松阪市人氣餐廳，並推薦具有歷史感的旅遊景點。\n\n除此之外，松阪市還有松阪豬和雞肉燒肉等不可錯過的美食。松阪真是不愧對「肉之都」的美名。\n\n松阪市也是座傳統工藝興盛的城市，編織技術在5世紀末傳入松阪，「松阪木棉」的製作持續至今。\n\n在松阪站徒步圈內的豪商之都松阪 觀光交流中心提供多語言服務，建議可來先這裡獲取觀光情報。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/06-223094.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/20-225268.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/06-223009.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/06-223019.webp"]'::jsonb, E'2025-02-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/25446', E'zh-Hant', 24, E'【三重】伊勢・VISON順遊推薦行程！和服體驗、享受松阪牛療癒之旅', E'前往三重縣旅遊時，除了經典的伊勢神宮與熱門的VISON之外，松阪市也絕對不能錯過。在這裡可以體驗穿上傳統的「松阪木棉」和服，品嚐頂級松阪牛，或享受溫泉帶來的放鬆時光。本篇文章將深入介紹松阪市不為人所知的魅力給大家！\n\n計劃前往三重縣旅遊時，除了參拜伊勢神宮，還有日本最大的商業度假設施「VISON」享受購物樂趣之外，還可以順道拜訪一個能讓身心靈都獲得深度療癒的地方！\n\n距離伊勢市與VISON僅約30至40分鐘車程，位在三重縣中部的歷史之城——松阪市，不僅交通便利，更擁有豐富的文化底蘊與令人垂涎的美食。\n\n提到松阪，大家一定會想到日本三大和牛的「松阪牛」，但這裡還有傳承自江戶時代的傳統織物「松阪木棉」、以及日本前三大茶葉產地三重縣中的「松阪茶」。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/07/24-239495.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/24-239496.webp","https://resources.matcha-jp.com/resize/720x2000/2025/08/15-241424.webp","https://resources.matcha-jp.com/resize/720x2000/2025/07/24-239498.webp"]'::jsonb, E'2025-07-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/24191', E'zh-Hant', 25, E'琵琶湖國定公園', E'琵琶湖國定公園（日語：琵琶湖国定公園／びわここくていこうえん，羅馬化：Biwako Kokutei Kōen），是位在日本滋賀縣、京都府的國定公園。\n\n1950年7月24日指定，是日本最早指定的國定公園。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225205.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225201.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225203.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225202.webp"]'::jsonb, E'2025-03-06'::timestamptz, E'琵琶湖國定公園', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E7%90%B5%E7%90%B6%E6%B9%96%E5%9C%8B%E5%AE%9A%E5%85%AC%E5%9C%92'),
(E'https://matcha-jp.com/tw/24192', E'zh-Hant', 25, E'琵琶湖國定公園', E'琵琶湖國定公園（日語：琵琶湖国定公園／びわここくていこうえん，羅馬化：Biwako Kokutei Kōen），是位在日本滋賀縣、京都府的國定公園。\n\n1950年7月24日指定，是日本最早指定的國定公園。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225209.webp","https://resources.matcha-jp.com/resize/720x2000/2025/03/05-227102.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225211.webp","https://resources.matcha-jp.com/resize/720x2000/2025/02/19-225210.webp"]'::jsonb, E'2025-03-05'::timestamptz, E'琵琶湖國定公園', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E7%90%B5%E7%90%B6%E6%B9%96%E5%9C%8B%E5%AE%9A%E5%85%AC%E5%9C%92'),
(E'https://matcha-jp.com/tw/22713', E'zh-Hant', 25, E'【關西滑雪】滋賀縣7大滑雪場攻略！奧伊吹、琵琶湖山谷、箱館山都適合親子玩雪', E'滋賀縣北部交通便利，從大阪、京都與名古屋輕鬆抵達，是關西居民短程滑雪的熱門地點。文章整理Grand Snow奧伊吹、琵琶湖山谷、箱館山與餘呉高原等四大經典雪場特色，包括適合親子的兒童區、纜車資訊、營業期間與夜滑體驗，並提醒交通接駁與票務安排，適合規劃一日或週末滑雪行程的家庭與初學者參考。\n\n自然資源豐富的滋賀縣北部地區降雪量多，擁有眾多滑雪場，且因交通便利，從大阪、京都和名古屋都能輕鬆抵達，因此非常受歡迎。\n\n有些滑雪場靠近高速公路交流道，有些則適合搭乘電車前往，讓我們一起找找最適合您計劃的滑雪場吧！\n\n▼滋賀縣滑雪場交通便利，從京阪神和名古屋都能輕鬆抵達 ▼包括關西最大級滑雪場！滋賀縣知名滑雪場排行榜4選', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/15-209520.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/15-209504.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/15-209506.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/18-209938.webp"]'::jsonb, E'2024-11-22'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/3704', E'zh-Hant', 26, E'【2026最新】京都春浪漫櫻花開滿天，22個超人氣賞花景點任您選！', E'在春季拜訪京都必定少不了賞櫻這項活動。美麗的街道和神社寺院與櫻花互相輝映的景象是京都獨特的美景。本篇文章將向大家介紹圓山公園、清水寺等人氣賞櫻景點加上市區外如七谷川等秘境賞花處。同時也提供賞花時期與櫻花種類的相關資訊供各位參考。\n\n在春天到訪古都京都，賞花是必不可少的一項體驗。在祇園或嵐山的渡月橋等歷史悠久的魅力街景下飄揚的櫻花，亦或是在以美麗的庭園聞名的高台寺下盛開的櫻花，無不宛如充滿幻想的繪畫。此外，在3月底至4月初的賞花季，部分景點也還有舉行點燈展。本篇文章將針對櫻花時節到訪的朋友介紹賞花景點與可以更盡情享受賞花的小秘訣。\n\n雖然花期會根據當年的氣候和地點有別，但京都的賞花季主要落在4月上旬至中旬這段期間，但基本上3月份的後半就會開花，4月前半到後半便會迎來滿開的賞花期。不過有些品種的櫻花在3月上旬就會開花，4月中旬才開花的花種也有。櫻花的花期很短，若是碰上下雨更是轉眼就結束了。大家前往各個景點賞花前請先在官方網站上確認好櫻花的開花狀況再出發。\n\n※2026年京都櫻花的開花日預估在3/25 ，滿開日則是落在4/1左右。（資訊來源：日本氣象株式會社）', E'["https://resources.matcha-jp.com/resize/720x2000/2016/12/07-11138.webp","https://resources.matcha-jp.com/resize/720x2000/2018/03/12-50202.webp","https://resources.matcha-jp.com/resize/720x2000/2018/02/08-47630.webp","https://resources.matcha-jp.com/resize/720x2000/2019/01/15-69381.webp"]'::jsonb, E'2016-12-30'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/4097', E'zh-Hant', 26, E'【京都】搭上走訪京都著名景點的「觀光特急巴士 (EX系統)」開啟京都賞櫻之旅吧！', E'擁有千年歷史的京都，每到春天，櫻花就優雅又張狂地綻放。但研究起京都交通，無限的轉乘與換車常讓人發愣。別擔心！京都市交通局已將舊有的觀光巴士升級，推出全新的「觀光特急巴士 (Tourist Express Bus)」，以更快速、更直達的方式帶您走訪人氣景點。\n\n原本熟悉的 100、101 路「洛巴士」已正式退役。取而代之的是專門疏導觀光人潮的EX特急路線，主要停靠熱門景點，避開通勤車潮。\n\nEX100 號： 由京都車站出發，快速連接清水寺、祇園、岡崎（平安神宮）、銀閣寺。 EX101 號： 由京都車站直達清水寺（五條坂）。 運行時間： 僅在六日及國定假日運行。\n\n為了維持乘車效率，目前的觀光巴士採取「前門上車付費、後門下車」的模式。 單程票價為500日圓，使用「地下鐵・巴士一日券」 (1,100 日圓)也能搭乘此巴士。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/02/27-20027.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/27-20028.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/27-20030.webp","https://resources.matcha-jp.com/resize/720x2000/2017/02/27-20031.webp"]'::jsonb, E'2017-02-27'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/160', E'zh-Hant', 26, E'平安神宮', E'平安神宮（日語：平安神宮／へいあんじんぐう，羅馬化：Heian Jingu）是位於京都府京都市左京區的神社。舊社格為官幣大社、勅祭社。\n\n現在是神社本廳的別表神社。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/08/23-34269.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/16-202836.webp","https://resources.matcha-jp.com/resize/720x2000/2017/08/23-34272.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/16-202837.webp"]'::jsonb, E'2016-02-22'::timestamptz, E'平安神宮', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%B9%B3%E5%AE%89%E7%A5%9E%E5%AE%AE'),
(E'https://matcha-jp.com/tw/4269', E'zh-Hant', 27, E'【2026大阪賞櫻】關西賞櫻名所「大阪造幣局」百樣品種櫻花齊放', E'關西賞櫻知名景點「大阪造幣局」，每年櫻花季必定吸引許多賞櫻人潮！擁有多樣櫻花品種，當櫻花盛開時就如置身於櫻花世界般，不論是紛紛飄落的櫻花雨，或是櫻花花瓣舖成的櫻花大道，都相當壯觀！2025年一起來關西的大阪造幣局追櫻吧！\n\n說到大阪賞櫻熱門景點除了大阪城公園、萬博公園外，種植上百品種櫻花的「大阪造幣局」，同樣被列為關西必去賞櫻名所喔！\n\n但每年櫻花祭，大阪造幣局會依據當年開花預想日程，開放為期一周「賞櫻通道」，解除門禁，開放民眾一齊賞櫻。\n\n大阪造幣局舊淀川沿岸有著全長560公尺的「賞櫻通道」，種植品種多達134樣，共350株櫻花樹，走在其中如沐櫻花雨，地面飄落的花瓣如櫻海，頭頂上交織著高貴優雅粉紅色系、純潔淡白色系、鮮豔桃紅色櫻花，各色系交錯其中。', E'["https://resources.matcha-jp.com/resize/720x2000/2020/01/31-96150.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/06-23516.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/06-23525.webp","https://resources.matcha-jp.com/resize/720x2000/2017/04/06-23522.webp"]'::jsonb, E'2017-04-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/6848', E'zh-Hant', 27, E'【2026最新】大阪賞櫻美景11選：人氣＆私房隱藏景點保存版', E'說到日本的花第一個想到的就是「櫻花」。日本自3月下旬開始花季從南而北開始，有機會春天造訪日本時一定不要錯過！ 本篇文章小編整理了大阪的11個賞櫻景點，快來看看唷！\n\n冬天到了尾聲，就來到了暖和的賞櫻季節。日本每年都有許多人為了賞櫻，特別到一些賞櫻景點。\n\n受海外旅客歡迎的觀光地大阪，可是有許多賞櫻景點呢，這次小編整理了我們推薦的11個賞櫻景點。 請大家一定要找幾個自己喜歡的地方走走！\n\n圖自「櫻花季節資訊 & 日本賞櫻景點 44選【2020保存版】」 「大川」是一條流經大阪府大阪市中心的河川，大阪賞櫻絕對少不了這個地方。理由是這裡可以看到約4,800棵的櫻花樹道，到了花季，整片被渲染成淡粉色，充滿著春天氣息。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/12/05-67443.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/05-67445.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/05-67447.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/26-68622.webp"]'::jsonb, E'2019-02-18'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/2692', E'zh-Hant', 27, E'大阪城', E'大坂城或大阪城（おおさかじょう），是位於現今大阪府大阪市中央區大阪城（上町台地的北端、攝津國東成郡生玉莊大坂）的一座日本城堡，最初建於安土桃山時代，並於江戶時代、舊帝國時代分別重建。\n\n別名為錦城（きんじょう，亦作金城）。該城作為「大阪城跡」被指定為國之特別史跡。此外，包含城址在內的一帶已規劃為大阪城公園（おおさかじょうこうえん）。\n\n於1931年重建的天守則作為博物館使用，稱為「大阪城天守閣」。在天下統一的桃山時代是豐臣秀吉的居城、豐臣政權的中心。後來德川家康以兩次大坂之役（冬之陣、夏之陣）消滅豐臣家；此後，江戶幕府以大坂城為控制西日本大名的重要據點。\n\n8公里）。在豐臣時代，大坂城曾經是全日本規模最大的城郭。', E'["https://resources.matcha-jp.com/resize/720x2000/2022/01/20-120963.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/20-120964.webp","https://resources.matcha-jp.com/resize/720x2000/2022/01/20-120965.webp","https://resources.matcha-jp.com/archive_files/jp/2016/09/osakakoyo20160901e.webp"]'::jsonb, E'2018-11-14'::timestamptz, E'大阪城', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%A4%A7%E9%98%AA%E5%9F%8E'),
(E'https://matcha-jp.com/tw/7423', E'zh-Hant', 28, E'姬路城', E'姬路城（日語：姫路城／ひめじじょう，羅馬化：Himeji-jō）是一座位於日本兵庫縣姬路市的城堡，為該市主體象徵。由於其白色的外牆，也被稱為白鷺城（白鷺城／はくろじょう・しらさぎじょう）。\n\n作為日本最具象徵意義，且保留度最為完整的城堡，姬路城是日本政府指定的國寶及國家特別史跡，也是日本首批世界文化遺產之一。為日本100名城之一。\n\n由於其保存度相當完好（城內的天守為日本的十二座現存天守之一），也被稱為「日本第一名城」。許多時代劇和電影也在這裡進行拍攝，或以姬路城作為江戶城的象徵。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/05/17-77186.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/16-77019.webp","https://resources.matcha-jp.com/resize/720x2000/2019/05/16-77046.webp","https://resources.matcha-jp.com/old_thumbnails/200x2000/2523.webp"]'::jsonb, E'2019-07-16'::timestamptz, E'姬路城', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%A7%AC%E8%B7%AF%E5%9F%8E'),
(E'https://matcha-jp.com/tw/3588', E'zh-Hant', 28, E'這不是歐洲！神戶經典景點「北野異人館街」建築六選', E'日本除了本身的和風日式老街外, 也有各式各樣的歐風街景並存, 不管是有歷史的歐式宅邸、外國人領事館, 或是近代建造的洋風建築, 都是構成日本歐風街景的一大特色。今天小編要來介紹的是位於兵庫縣神戶市的北野地區, 這裡的洋風建築建於明治或大正時期，這些異人館建築形成了今天神戶的經典觀光景點之一。\n\n目次 神戶為何擁有這般歐風街景 北野異人館建築6選 神戶為何擁有這般歐風街景 江戶幕府於1858年與美國簽訂條約, 日本承諾開放函館、新潟、神奈川橫濱、兵庫神戶、長崎等五個港口, 並於開港地沿海區域規劃外國人居留地, 因為來日的外國人不斷增加, 原本設置的外國人居留地土地不夠用, 許多外國人因此開始聚集於稍微偏離三宮市街, 位於可以看到海的高地北野町山本通地區建造宅邸, 這些外國人的建築日本稱作「異人館」。\n\n第二次世界大戰日本戰敗後神戶市街被破壞的很嚴重, 神戶北野町山本通南側也無一倖免, 不過北側地區很幸運的躲過空襲的摧殘, 保留了戰前那異國情緒滿懷的街道及優雅的氣氛。\n\n從三宮市街沿著指標慢慢爬上坡道, 北野町地區沿路上有許多有歷史的建築物, 外觀自由參觀, 其中公開可入內參觀的建築約有18個, 有些則需要購買門票。讓小編來介紹幾個比較知名的異人館吧!', E'["https://resources.matcha-jp.com/resize/720x2000/2016/11/24-10155.webp","https://resources.matcha-jp.com/resize/720x2000/2016/11/11-8823.webp","https://resources.matcha-jp.com/resize/720x2000/2016/11/11-8814.webp","https://resources.matcha-jp.com/resize/720x2000/2016/11/11-8815.webp"]'::jsonb, E'2016-11-24'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7352', E'zh-Hant', 28, E'不要讓別人知道！神戶超私房夜景景點「諏訪山公園 維納斯橋」', E'提到神戶夜景，六甲山、摩耶山夜景廣為觀光客所知。而離市區約半小時的維納斯橋（諏訪山公園展望台），其實更是當地情侶們喜愛的約會景點。可以飽覽神戶夜景、還有情侶愛的愛之鎖紀念碑。少去人擠人的煩惱，不僅浪漫度增加、告白機率也更高！\n\n目次 愛與美的女神「維納斯橋」的浪漫命名 鎖上愛之鎖 象徵永恆的愛情 「神戶百萬夜景」豆知識 結語 賞神戶百萬夜景不必再舟車勞頓！神戶情侶的私房約會景點「維納斯橋」正在神戶元町北方的諏訪山公園內，距離市區15分鐘車程。擁有遼闊視野，能盡覽美利堅公園的神戶塔和摩天輪，遠離嘈雜觀光客熱點，漫步螺旋橋上，幽靜的觀賞這片夜景吧！\n\n早年有觀星隊在此觀測到金星，把展望台稱作「金星台」；後來這座總長約90公尺8字型的螺旋橋樑建置後，成為觀光熱點。金星英文名稱維納斯，象徵愛與美的女神，因此被取作維納斯橋，浪漫的名稱加上美麗景緻，讓這座觀景台更增添甜蜜氣息。\n\n螺旋橋落成沒多久，情侶間深信「和喜歡的人一起走在維納斯橋上，在橋上鎖上對彼此的誓言，會幸福一輩子。」欄杆上鎖滿情侶間許下愛之誓言鎖頭，但隨著日曬雨淋，欄杆鏽蝕，被認為有礙觀瞻。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75839.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75840.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75841.webp","https://resources.matcha-jp.com/resize/720x2000/2019/04/23-75807.webp"]'::jsonb, E'2019-04-23'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/19933', E'zh-Hant', 29, E'东大寺', E'東大寺（日語：東大寺／とうだいじ，羅馬化：Tōdai Ji）位於日本奈良縣奈良市雜司町，是日本佛教華嚴宗大本山、南都七大寺之一。\n\n1998年作為「古都奈良的文化財」的一部分被列為世界文化遺產。東大寺由信奉佛教的聖武天皇興建於728年，因為建在首都平城京以東而得名，另外有西大寺相對應。\n\n其後聖武天皇在日本各地興建68餘座國分寺（正式名稱為「金光明四天王護國之寺」），東大寺是階位最高的總寺院。此寺大佛殿正面寬度57米，深50米，為世界最大的木造建築，殿內供奉高15米以上的盧舍那大佛像。\n\n寺院內還有南大門、二月堂、三月堂、正倉院等建築，其中南大門有很著名的雙體金剛力士像；二月堂能夠俯視大佛殿和眺望奈良市區。', E'["https://resources.matcha-jp.com/resize/720x2000/2025/10/09-246358.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/20-198167.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/20-198169.webp","https://resources.matcha-jp.com/resize/720x2000/2024/09/20-198171.webp"]'::jsonb, E'2024-10-02'::timestamptz, E'东大寺', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E4%B8%9C%E5%A4%A7%E5%AF%BA'),
(E'https://matcha-jp.com/tw/1365', E'zh-Hant', 25, E'【關西】日本關西地區完全攻略！2府4縣必去景點、特色美食一網打盡', E'關西地方包括大阪府、京都府、兵庫縣、奈良縣、滋賀縣和和歌山縣，共計2府4縣。當這2府4縣再加上三重縣時，則被稱為「近畿地方」。在這篇文章中，抹茶將為大家介紹關西地區交通方式，以及各縣市的代表景點和當地必吃美食，讓各位深入了解日本關西地區。\n\n在日本全國47個都道府縣中，很受訪日觀光客歡迎的就是關西地區。所謂的關西包含哪些地區呢？當談到日本關西地區，許多人首先想到的是熱鬧的大阪、文化底蘊深厚的京都和古樸的奈良。然而，關西地方的魅力不僅僅止於此，還涵蓋了許多不容錯過的迷人地區。\n\n本篇為你介紹日本關西景點與當地特色美食，帶你了解這個充滿活力與魅力的西日本。來去關西走一趟，感受這片土地的魅力與溫暖吧！\n\n「關西」指的是「關所以西的地區」，而「關所」是指設置在交通要道，用來監視人員和物品的設施。過去的人們不像現在這樣可以自由前往日本各地，必須經過關所的檢查，或通行證許可才能通行。當京都還是日本首都的年代時，逢坂的關所（位於大阪、滋賀縣）以西的地區，被稱為「關西」。', E'["https://resources.matcha-jp.com/archive_files/jp/2015/11/kansai_map_20151106.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/15-202631.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/15-202665.webp","https://resources.matcha-jp.com/resize/720x2000/2024/10/15-202693.webp"]'::jsonb, E'2018-08-06'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/27422', E'zh-Hant', 26, E'2026年8月關西盛夏指南！大阪、京都、奈良、神戶慶典與活動總整理', E'一起探索大阪、京都、奈良與神戶最具代表性的8月盛事！從享譽盛名的京都五山送火、夢幻浪漫的奈良燈花會，到震撼全場的琵琶湖花火大會，一起享受關西熱鬧又感性的夏日夜空吧！\n\n日本 8 月最矚目的焦點莫過於盂蘭盆節（Obon），這是月中專為祭奠先祖而舉辦的傳統活動時期。\n\n包含大阪、京都、奈良與神戶在內的關西地區，將舉辦多場指標性祭典，能讓您深入體驗日本文化。\n\n主要盛事包括點亮環繞城市五座山頭巨大送火的京都「五山送火」、以 20,000 盞搖曳燭光妝點奈良公園的「奈良燈花會」，以及壯觀的「琵琶湖大煙火大會」。', E'["https://resources.matcha-jp.com/resize/720x2000/2026/07/23-267741.webp","https://resources.matcha-jp.com/resize/720x2000/2026/07/23-267742.webp","https://resources.matcha-jp.com/resize/720x2000/2026/07/23-267743.webp","https://resources.matcha-jp.com/resize/720x2000/2026/07/23-267744.webp"]'::jsonb, E'2026-07-30'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/23256', E'zh-Hant', 26, E'2026關西新年參拜景點10選：人氣神社、能量景點與秘境懶人包', E'整理關西地區十大新年參拜景點，從大阪住吉大社、大阪天滿宮到京都平安神宮與伏見稻荷大社，並收錄下鴨神社、玉置神社等較少人潮或強力能量點。文內提供各神社地址、例年參拜時間與官方連結，並建議避開尖峰時段與適合情侶、親子與考生的參拜選擇，是規劃關西跨年或新年旅行的實用指南。\n\n這次為正在尋找關西新年參拜地點的你，精選關西推薦的新年參拜景點排行榜10選。並收錄秘境景點、適合情侶或親子的推薦地點，歡迎作為參考！\n\n住吉大社以大阪最強的能量景點著稱，當地人親切稱呼為「すみよっさん」。主要祈求商業繁盛、結緣、家內平安等，從除夕到三賀日相當熱鬧。2025年無屋台出店，2026年屋台資訊尚未公布。去年有護身箭、生肖土人偶等可愛的吉祥物，值得一看。\n\n【住吉大社】 地址：〒558-0045 大阪府大阪市住吉区住吉2丁目9−89 例年參拜時間： ・12月31日 22：00〜 ・1月1日 ～20：00 ・1月2・3日 6：00〜19：00 ・1月4・5日 6：00〜18：00 官方網站：https://www.sumiyoshitaisha.net/ 官方社群：Instagram、Facebook', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/16-215473.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/16-215474.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/16-215472.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/16-215476.webp"]'::jsonb, E'2025-11-05'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/11772', E'zh-Hant', 29, E'【2026】奈良賞櫻景點8選！欣賞寺廟、小鹿與櫻花共演的絕景', E'古都奈良是比京都悠久的城市，奈良縣內也有許多賞櫻景點，在每年的3月下旬〜甚至是到5月上旬期間都有機會能欣賞到古刹寺廟與粉櫻共演的絕景，本文整理出能利用JAPAN RAIL PASS或近鐵電車周遊券抵達的賞櫻景點8個，以及各景點的開花情報。\n\n奈良市内就有8座寺廟和史蹟被登錄在世界文化遺產，加上四周自然資源豐富，擁有高原和高山等大自然美景、以及各種不同種類的櫻花，從3月下旬到5月上旬，共有一個多月賞花時間，賞花時間長、以及同時欣賞到歷史文化建築與櫻花共演，正是到奈良賞櫻的魅力之處。\n\n「奈良公園」內總是群聚著約1200稱為「神的使者」的野生鹿群，加上附近有春日大社、興福寺、東大寺等貴重的歴史文化遺產景點，這樣的景色成為代表奈良的觀光名勝。\n\n一到春天就會約1,700株的櫻花樹綻放，在櫻花花瓣灑落一地的粉色絨毯上，優雅地鹿群，背景又是歷史悠久的寺廟，三者共演之下成為「櫻花名所100選」，同時也是只有奈良才有的景色。', E'["https://resources.matcha-jp.com/old_thumbnails/200x2000/672.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/03-135224.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/10-135788.webp","https://resources.matcha-jp.com/resize/720x2000/2023/03/10-135789.webp"]'::jsonb, E'2023-03-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/6867', E'zh-Hant', 29, E'『大阪ー奈良』世界遺產巡鹿快閃一日遊－飽覽必訪景點與打卡熱點', E'2019年春天大阪東線（おおさか東線）開通，只需要1個小時便可從新大阪直接搭到奈良。早上先到奈良感受神聖古樸的氣質，晚上回到大阪逛街享受多采多姿的夜生活與大啖美食。本文為此安排了大阪到奈良一天行程，並整理了奈良的特色景點和各項伴手禮，雖然只是一天的快閃行程，還是能在短短時間內感受奈良的獨特魅力。\n\n大阪東線（おおさか東線）將在2019年春天全面開通，新幹線新大阪站直通奈良，車程縮短成大約1個小時，住在新大阪站附近的旅客也不用先到天王寺換車，早上可以直接先往奈良踩點，再回來大阪享受多采多姿的夜生活，為此小編在這裡安排了大阪到奈良的當天來回快閃行程，裡面包括奈良的特色景點和真心推薦的伴手禮，雖然只是短短不到一天時間，還是能把握時間感受奈良的獨特魅力。\n\n画像：JR西日本プレスリリース 根據2018年的資料，從新大阪到奈良間的運費約為920日圓左右，若是開通之後價格應該也維持原價，時間則約為1個小時上下。若是不用大阪東線而改用其他交通方式，像是轉進市區到天王寺改搭大阪METRO的交通資訊，所需的交通費試算如下： 新大阪➞（大阪メトロ御堂筋線）➞天王寺➞（JR大和路線）➞奈良 交通費＝大阪METRO280日圓＋JR470日圓＝750日圓 時間＝約1個小時又11分左右 比起大阪東線，繞到天王寺站的方式多出了11分鐘，便宜了170日圓。\n\n奈良車站於1934年（昭和9年）改建完成的車站，十分氣派壯觀的外觀走的是和洋折衷調性，一大早抵達奈良，可以先這家星巴克併設於奈良市綜合觀光諮詢處，填飽肚子順便收集一下觀光資訊再出發。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/12/10-67718.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/13-11528.webp","https://resources.matcha-jp.com/resize/720x2000/2016/12/13-11531.webp","https://resources.matcha-jp.com/resize/720x2000/2017/06/05-28016.webp"]'::jsonb, E'2018-12-04'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/6666', E'zh-Hant', 30, E'和歌山城', E'和歌山城是一座位於日本和歌山縣和歌山市市中心的梯郭式平山城，因為位於虎伏山上，所以又稱為虎伏城。紀之川流經和歌山城的北部，為城堡天然的護城河。\n\n它與松山城、姬路城合稱日本三大連立式平山城。和歌山城曾經為德川御三家中治理紀伊藩（又名紀州藩、和歌山藩）的紀伊德川家的居所，紀伊藩的的第五代藩主吉宗和第十三代藩主慶福，後來分別成為幕府第八代將軍德川吉宗和第十四代將軍德川家茂。\n\n和歌山城曾經被日本指定為國寶，但是後來在第二次世界大戰期間遭到美軍轟炸而燒毀，現在的和歌山城是於1958年所重建完成的。\n\n和歌山縣出身的企業家松下幸之助對於和歌山城重建提供許多資金。德川御三家的城郭非常的遼闊，現在和歌山城的面積只有極盛時期的4分之1而已。曾經是和歌山城內的地方包括了現在的和歌山市政府、和歌山市消防局、和歌山地方法院、和歌山家庭裁判所、和歌山地方檢察廳以前官方組織和學校、商業設施、辦公室街與和歌山中央郵局等地區，是規模非常大的城堡，但其實本來預定建造的城堡規模是更巨大的。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/10/05-64076.webp","https://resources.matcha-jp.com/resize/720x2000/2018/10/29-65493.webp","https://resources.matcha-jp.com/resize/720x2000/2018/10/05-64078.webp","https://resources.matcha-jp.com/resize/720x2000/2018/10/15-64614.webp"]'::jsonb, E'2019-01-23'::timestamptz, E'和歌山城', E'Wikipedia (CC BY-SA 4.0)', E'https://zh.wikipedia.org/wiki/%E5%92%8C%E6%AD%8C%E5%B1%B1%E5%9F%8E'),
(E'https://matcha-jp.com/tw/23224', E'zh-Hant', 30, E'和歌山的美食五選！醃壽司、拉麵等美食排名介紹', E'本文將介紹和歌山縣的代表性美食，以及實際可以品嚐的熱門店家。和歌山縣擁有多樣的美食，像是和歌山拉麵、醃壽司和梅壽司等。在前往觀光時，請參考本文所介紹的店家，享受地道的美味吧！\n\n在前往和歌山縣旅遊時，這裡有一些絕對不能錯過的美食推薦，以排名的形式介紹。本文也將介紹能夠品嚐和歌山美食的熱門店家，作為觀光選擇的參考。\n\n▼和歌山市內觀光推薦！必吃的名產與B級美食 ▼和歌山代表美食多樣！ ▼1位. 和歌山拉麵\n\n和歌山的三大美食是「和歌山拉麵」、「醃壽司」和「梅壽司」。尤其是和歌山拉麵受到廣泛喜愛，和歌山市內有許多店家可供選擇。', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215024.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215025.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215026.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/13-215027.webp"]'::jsonb, E'2024-12-20'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/23027', E'zh-Hant', 30, E'和歌山觀光的示範行程（半日、一日遊、兩天一夜）！詳細介紹當地美食和絕美景點', E'和歌山縣以其豐富的自然美景、美麗的海岸線和歷史名勝而聞名。本文將根據半日、一日遊和兩天一夜的行程，來介紹和歌山的示範觀光行程。\n\n和歌山縣是自然、歷史與美食融合的魅力地區。擁有熊野古道和高野山等世界遺產，散發著神秘的氛圍。美麗的南紀白浜和勝浦溫泉則是放鬆身心的理想場所。\n\n本文將詳細介紹充滿和歌山魅力的模型路線。根據不同的行程安排，提供參考以便於您的和歌山觀光計劃。\n\n【半日（下午〜夜）觀光模型路線】 圓月島→白良濱→千畳嶺→晚餐時間（海鮮市場南紀白浜）', E'["https://resources.matcha-jp.com/resize/720x2000/2024/11/30-213030.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/30-213029.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/30-213031.webp","https://resources.matcha-jp.com/resize/720x2000/2024/11/30-213032.webp"]'::jsonb, E'2024-12-10'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/5175', E'zh-Hant', 31, E'推薦鳥取大山的周遊路線！用「Loople bus 」充分享受絕景、美食、寺院、美術館', E'在鳥取縣的人氣觀光景點大山除了享受多姿多彩的活動以外，還有很多風景勝地、寺院、美術館和美食。在此介紹利用「大山Loople bus 巡迴巴士」，具有當季魅力和交通便利的實惠一日周遊路線。\n\n位於鳥取縣西部的大山(Daisen)是高度為1729公尺的中國地方的最高山峰。入選日本國營電視臺(NHK)進行的日本名峰排名榜，僅次於富士山、槍嶽，被選為最佳前三名。\n\n因為其在春夏的新緑、秋天的紅葉、冬天的雪所覆蓋之下的身姿等美景，自古以來就被當地人作為神所在的山而崇拜。現在成為了能夠享受絕景、史跡、美食、戶外活動的人氣景點，很受歡迎。\n\n冬天開放的大山White Resort（白色度假村）是西日本最大的滑雪勝地。能夠在眺望弓浜和日本海的絕景中滑雪。', E'["https://resources.matcha-jp.com/resize/720x2000/2017/10/11-38320.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/11-38322.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/10-38221.webp","https://resources.matcha-jp.com/resize/720x2000/2017/10/24-39440.webp"]'::jsonb, E'2018-07-02'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/6868', E'zh-Hant', 31, E'親近美麗自然楓景！鳥取必訪紅葉景點六選', E'鳥取縣坐擁豐富的大自然美景，不僅有遼闊茂密的山林還有充滿綠意的公園。秋季拜訪西日本時，可別錯過鳥取縣令人驚豔的楓葉美景。就讓小編帶你遊遍六個鳥取縣絕美楓葉景點。\n\nPicture on the upper right courtesy of Tottori Prefecture\n\n鳥取縣坐擁豐富的自然美景，有許多迷人的山巒、森林及公園，尤其秋天景色更是美不勝收。鳥取縣的最佳紅葉觀賞時期為11月中旬至12月上旬。\n\n大山是西日本最棒的賞楓景點之一。所處緯度較高，森林在10月初左右就染上了秋天的色彩。', E'["https://resources.matcha-jp.com/resize/720x2000/2018/12/17-68226.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/05-67511.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/05-67513.webp","https://resources.matcha-jp.com/resize/720x2000/2018/12/05-67512.webp"]'::jsonb, E'2019-01-21'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/5560', E'zh-Hant', 31, E'全日第一蟹王之鄉！鳥取「境港」美食全攻略！', E'鳥取縣境港市的境漁港，天然鮪魚及紅楚蟹的漁獲量可是全日本第一！周邊還有許多海鮮極品名店和土產店。另外，境漁港還可以看到築地市場見不到的「漁船卸貨」場景呢！\n\n鳥取縣西部的境港市境漁港是日本少數的漁港。特別是天然鮪魚和紅楚蟹的漁獲量可是日本第一。\n\n或許你會想說「要在漁港觀光？這樣能看什麼呢？」，不用著急，看以下介紹你一定會漸漸愛上這裡。\n\n境漁港周邊有很多可以吃到極品海鮮美食的食堂，還有可以買到海產伴手禮的商店，也就是說可以當作美食之旅。另外，還可以參觀難得見到的漁船卸貨！', E'["https://resources.matcha-jp.com/resize/720x2000/2017/12/22-44670.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/22-44672.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/21-44615.webp","https://resources.matcha-jp.com/resize/720x2000/2017/12/22-44673.webp"]'::jsonb, E'2018-03-22'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/23083', E'zh-Hant', 32, E'【2026】島根縣「出雲大社」參拜結緣攻略！超巨大注連繩與星巴克都在這裡', E'出雲大社位於島根縣，是日本最古老且文化深遠的神社之一，以供奉結緣之神大國主大神聞名，吸引無數旅客前來祈求戀愛與幸福。想親自感受日本出雲大社的魅力，不妨藉由這篇文章來認識出雲大社交通方式與其他實用資訊，輕鬆前往這個神聖之地，探索它的歷史與美麗傳說！\n\n而主祭神大國主大神被尊為「結緣之神」，吸引許多人到出雲大社祈求戀愛、婚姻與人生良緣，也因此成為膾炙人口的能量景點。\n\n日本出雲大社本殿採用日本最古老的「大社造」神社建築風格，現存的結構於18世紀重建，高24公尺，為國寶級建築，氣勢恢宏。而在神樂殿前那條重達5.2噸的出雲大社巨大注連繩更是讓人驚艷！\n\n出雲大社參拜時間：6:00 - 19:00（其中十九社以北在16:30後會關閉） 出雲大社參拜費用：免費', E'["https://resources.matcha-jp.com/resize/720x2000/2024/12/04-213530.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/04-213531.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/04-213538.webp","https://resources.matcha-jp.com/resize/720x2000/2024/12/04-213541.webp"]'::jsonb, E'2024-12-04'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/17526', E'zh-Hant', 31, E'自行車3天2夜體驗島根、鳥取的旅遊魅力！享受療癒身心的溫泉、美食、美景', E'島根縣以結緣能量景點出雲大社而聞名全世界，鳥取縣則以充滿妖怪青銅像的水木茂之路而備受大人小孩的喜愛，而兩縣的共通特徵則是擁有許多溫泉、在地美食以及自然美景。本篇文章將介紹橫跨島根、鳥取兩縣的3天2夜自行車之旅。\n\n本篇將介紹橫跨島根、鳥取兩縣的3天2夜自行車之旅，旅途中將能享受療癒身心的溫泉、在地美食以及無敵美景，絕對會是喜愛自行車的人所不能錯過的旅遊體驗內容！\n\n目次 第一天：島根縣 第二天：鳥取縣・島根縣 第三天：鳥取縣 第一天：島根縣 9:30～ 出雲結緣機場 近幾年來由於托運自行車的旅客越來越多，因此出雲結緣機場為了提升自行車用者的服務，因此特別於1樓綜合案內所提供免費的自行車打氣筒租借服務。讓抵達機場的自行車旅客，在組裝自行車時可以更加便利！\n\n出雲大社祀奉著被稱為「結緣之神」的大國主大神，由於祂的心性善良曾經救過一隻白兔，因此又以「因幡白兔神話」而廣為人知，出雲大社內也因此於多處設置許多白兔石像。', E'["https://resources.matcha-jp.com/resize/720x2000/2023/12/17-157653.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/17-157655.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/17-157638.webp","https://resources.matcha-jp.com/resize/720x2000/2023/12/17-157639.webp"]'::jsonb, E'2023-12-17'::timestamptz, null, null, null),
(E'https://matcha-jp.com/tw/7642', E'zh-Hant', 32, E'2025最新【島根縣】不只有出雲大社！島根自由行11大必去景點・交通方式・美食攻略', E'島根縣有出雲大社和松江的城下町等許多歴史悠久名勝景致，還有玉造和溫泉津等溫泉勝地，宍道湖和隠岐諸島的景色也充滿魅力。本文將介紹島根縣的必去景點、從東京和大阪出發的交通方式、當地美食等攻略。\n\n出雲大社自古以來就是人們信奉的日本全國眾神集結的神社，現在則是有名的良緣(※1)景點。島根的中心松江是保留古色古香風景的城下町。除了可以欣賞許多日本繪畫和日本庭園的「足立美術館」，還有蜆的漁獲量日本第一的宍道湖。\n\n松江附近的玉造和溫泉津等溫泉街也可以放鬆。縣内可以品嘗鱸魚等海鮮，還有出雲蕎麥麵、島根和牛和日本酒等豐富美食。\n\n搭船前往的隠岐諸島島後有日本海的浪花拍打下形成的斷崖峭壁和美麗的夕陽等風景。 用有日本歴史建築、文化和大自然的島根。以下介紹幾個必去的景點。', E'["https://resources.matcha-jp.com/resize/720x2000/2019/07/09-81186.webp","https://resources.matcha-jp.com/resize/720x2000/2019/09/04-85224.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/09-81187.webp","https://resources.matcha-jp.com/resize/720x2000/2019/07/09-81188.webp"]'::jsonb, E'2019-10-12'::timestamptz, null, null, null)
